/// <summary>
/// The QR code of a device setup code (New device setup code, Show QR code). The code itself is not
/// kept: Show QR code gives the code a new value, and the QR code shown before stops working.
/// </summary>
[Form]
public class HSMobileOpsDeviceSetupQr extends FormRun
{
}

public void init()
{
    str setupText;

    super();
    setupText = element.args() ? element.args().parm() : '';
    if (!setupText)
    {
        throw error('Open this from New device setup code.');
    }
    QrText.text(setupText);
    QrImage.image(new Image(HSMobileOpsDeviceSetupCodeNew::qrPng(setupText)));
}

/// <summary>
/// The QR code as a PNG file (user, 16 Nov 2026) - to print or send to whoever sets up
/// the handheld. The same code as on screen: it works until it is used or reissued.
/// </summary>
public void clicked()
{
    super();
    container png = HSMobileOpsDeviceSetupCodeNew::qrPng(QrText.text(), 600);
    System.IO.Stream stream = Binary::constructFromContainer(png).getMemoryStream();
    File::SendFileToUser(stream, 'device-setup-code-' + date2Str(today(), 321, DateDay::Digits2, DateSeparator::Hyphen, DateMonth::Digits2, DateSeparator::Hyphen, DateYear::Digits4, DateFlags::None) + '.png');
}
